import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import ApiService from '../../Services/ApiService';
import { toast } from 'react-toastify';

export default function SellerReels() {
    const navigate = useNavigate();
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Initialize Remix Icons if available
        if (window.RemixIcon) {
            window.RemixIcon.init();
        }
        
        loadSellerReels();
    }, []);

    const loadSellerReels = async () => {
        try {
            setLoading(true);
            
            // Get seller reels from API
            // Note: In a real app, you would get the vendor ID from auth context or props
            const vendorId = 1; // Placeholder - in real app this would come from auth
            const response = await ApiService.getSellerReels(vendorId);
            
            if (response.success) {
                // Group reels by product and calculate counts
                const productMap = {};
                
                // Process each reel to get product information
                for (const reel of response.data) {
                    // Get product IDs from the reel
                    const productIds = reel.product_ids || [];
                    
                    if (productIds.length > 0) {
                        // For each product in the reel, create/update product group
                        for (const productId of productIds) {
                            // Since we don't have product names yet, we'll use a placeholder
                            // and update it later
                            const productKey = `product_${productId}`;
                            
                            if (!productMap[productKey]) {
                                productMap[productKey] = {
                                    productId: productId,
                                    product: `Product ${productId}`, // Temporary name
                                    reelCount: 0,
                                    reels: [],
                                    // Take properties from the first reel for display
                                    title: reel.title,
                                    category: reel.category_name || 'N/A',
                                    status: reel.status,
                                    views: 0,
                                    likes: 0,
                                    date: reel.created_at ? new Date(reel.created_at).toISOString().split('T')[0] : 'N/A'
                                };
                            }
                            
                            productMap[productKey].reelCount += 1;
                            productMap[productKey].reels.push(reel);
                            // Accumulate views and likes
                            productMap[productKey].views += reel.views || 0;
                            productMap[productKey].likes += reel.likes || 0;
                        }
                    } else {
                        // Handle reels with no products (fallback)
                        const unknownProductKey = 'unknown_product';
                        if (!productMap[unknownProductKey]) {
                            productMap[unknownProductKey] = {
                                productId: null,
                                product: 'Unknown Product',
                                reelCount: 0,
                                reels: [],
                                title: reel.title,
                                category: reel.category_name || 'N/A',
                                status: reel.status,
                                views: 0,
                                likes: 0,
                                date: reel.created_at ? new Date(reel.created_at).toISOString().split('T')[0] : 'N/A'
                            };
                        }
                        
                        productMap[unknownProductKey].reelCount += 1;
                        productMap[unknownProductKey].reels.push(reel);
                        productMap[unknownProductKey].views += reel.views || 0;
                        productMap[unknownProductKey].likes += reel.likes || 0;
                    }
                }
                
                // Convert to array format
                let groupedReels = Object.values(productMap);
                
                // Now fetch product names for all product IDs
                const allProductIds = [...new Set(groupedReels.map(r => r.productId).filter(id => id))];
                if (allProductIds.length > 0) {
                    try {
                        const productNamesResponse = await ApiService.getProductNamesByIds(allProductIds);
                        if (productNamesResponse.success) {
                            const productNamesMap = productNamesResponse.data;
                            
                            // Update product names in the grouped reels
                            groupedReels = groupedReels.map(reelGroup => {
                                if (reelGroup.productId && productNamesMap[reelGroup.productId]) {
                                    return {
                                        ...reelGroup,
                                        product: productNamesMap[reelGroup.productId]
                                    };
                                } else if (reelGroup.productId) {
                                    // Fallback to product ID if name not found
                                    return {
                                        ...reelGroup,
                                        product: `Product ${reelGroup.productId}`
                                    };
                                }
                                return reelGroup;
                            });
                        }
                    } catch (error) {
                        console.error('Error fetching product names:', error);
                        // Continue with default product names
                    }
                }
                
                setReels(groupedReels);
            } else {
                toast.error('Failed to load reels: ' + response.message);
                setReels([]);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading seller reels:', error);
            toast.error('Failed to load reels: ' + error.message);
            setLoading(false);
            setReels([]); // Set empty array instead of fallback data
        }
    };

    const handleViewReelVideo = async (productId) => {
        // Navigate to the view page for this product
        navigate(`/studio/seller/reels/${encodeURIComponent(productId)}`);
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">My Reels</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Reels Management</h5>
                        {/* Removed Upload Reel button */}
                    </div>
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : reels.length === 0 ? (
                            <div className="text-center py-5">
                                <h5>No reels found</h5>
                                <p className="text-muted">Upload your first reel to get started.</p>
                                <Link to="/studio/seller/upload" className="btn btn-success">
                                    <i className="ri-upload-line me-1"></i> Upload Reel
                                </Link>
                            </div>
                        ) : (
                            <div className="table-responsive">
                                <table className="table table-hover align-middle mb-0">
                                    <thead>
                                        <tr>
                                            <th>Product Name</th>
                                            <th>Reel Count</th>
                                            <th>Title</th>
                                            <th>Category</th>
                                            <th>Status</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Date</th>
                                            <th>Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {reels.map((productGroup, index) => (
                                            <tr key={index}>
                                                <td>{productGroup.product}</td>
                                                <td>{productGroup.reelCount}</td>
                                                <td>{productGroup.title}{productGroup.reelCount > 1 ? ` (+${productGroup.reelCount - 1} more)` : ''}</td>
                                                <td>{productGroup.category || 'N/A'}</td>
                                                <td>{getStatusBadge(productGroup.status)}</td>
                                                <td>{productGroup.views}</td>
                                                <td>{productGroup.likes}</td>
                                                <td>{productGroup.date}</td>
                                                <td>
                                                    <button 
                                                        className="btn btn-sm btn-info"
                                                        onClick={() => handleViewReelVideo(productGroup.productId || productGroup.product)}
                                                        title="View Reels"
                                                    >
                                                        <i className="ri-eye-line"></i> View
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
